# noqa
import re
import requests
import os
import xml.etree.ElementTree as ET

from os import listdir
from os.path import isfile, join
from pathlib import Path
from operator import methodcaller
from requests.exceptions import InvalidSchema
from auto_config.generator.utils.logger import logger


class BuildTranslator:
    PDDB_MAP_PATH = Path('/opt/emssim/pddb/pddb.map')
    PDDB_PATH = Path('/opt/emssim/pddb/')
    ENB_PARAMS_PATH = Path(os.path.abspath(__file__)).parents[2] / "config" / "ENB_PARAMS"
    RELEASE_PATT = r'^(5?\D+|\D+4GVDU|\D+5GCCU|\D+5GVDU)(\d{2})(ASP1|C|ASP|B|A|S4|SP|R)?(\d+)?'

    def __init__(self, build=None):
        # build=<RELEASE_TYPE><RELEASE>_<TYPE>_<MAJOR>_<MINOR>
        # e.g.: SBTS23R1_ENB_9999_230124_000012:
        #   RELEASE_TYPE=SBTS
        #   RELEASE=23R1
        #   TYPE=ENB_9999
        #   MAJOR = 230124
        #   MINOR = 12

        self.build = build
        if build is None:
            logger.info('Build not passed: using the latest one from pddb')
            self.build = self.get_latest_file(r'SBTS(\d+)R(\d+)_')

        self.build_release = ''
        self.pddb_version = ''
        self.pddb_release = ''
        self.pddb_release_number = 0
        self.pddb_release_major = 0
        self.pddb_release_minor = 0
        self.pddb_filename = ''
        self.set_rel()
        self.set_pddb()

        self.pddb_release_n1 = ''
        self.pddb_release_number_n1 = 0
        self.pddb_filename_n1 = ''

    def set_rel(self):
        build_matches = re.match('^([^_]+)_*', self.build)
        self.build_release = build_matches.group(1)
        self.pddb_release = self.build_release

    def set_pddb(self):
        pddb_file = self.get_pddb_file()
        rel_str, rel_float_str, major, minor = self.decompose_pddb_ver(self.pddb_version)
        self.pddb_file_path = self.PDDB_PATH / pddb_file
        self.pddb_release_number = rel_float_str
        self.pddb_release_major = major
        self.pddb_release_minor = minor
        logger.info(f"Using PDDB: {self.pddb_file_path}")
        logger.info(f"PDDB Version: {self.pddb_version}")
        logger.info(f"PDDB {rel_str}: {rel_float_str}/{major}/{minor}")

    def set_pddb_version(self, build):
        pddb_version = re.search(r'^([^_]+)(_*.*)', build)
        self.pddb_release = pddb_version.group(1)
        self.pddb_version = self.pddb_release + pddb_version.group(2)
        trunk_rel_typ = self.trunk_rel_typ(self.build_release)
        if trunk_rel_typ:
            logger.info(f"Changing trunk release {trunk_rel_typ} to pddb release={self.pddb_release}")
            self.build_release = self.pddb_release

    def trunk_rel_typ(self, build):
        rel_str, _, _, _ = self.decompose_build_id(build)
        if not rel_str:
            rel_str = build
        srch = re.search(r'^(\S+)00$', rel_str)
        if srch:
            return srch.group(1)
        return ''

    def get_pddb_file(self):
        pddb_file_from_map = self.get_pddb_file_from_map()
        if pddb_file_from_map:
            logger.info(f'PDDB FILE from map: {pddb_file_from_map}')
            self.set_pddb_version_from_file_name(pddb_file_from_map)
            return pddb_file_from_map
        else:
            logger.info(f'No PDDB FILE in map for build={self.build}')

        rel_typ = self.trunk_rel_typ(self.build)
        if rel_typ:
            latest_pddb_file = self.get_latest_file_of_typ(rel_typ)
            if latest_pddb_file:
                self.build_release, _, _, _ = self.decompose_pddb_ver(latest_pddb_file)
                self.set_pddb_version_from_file_name(latest_pddb_file)
                logger.info(f'PDDB FILE latest trunk: {latest_pddb_file} for pddb rel typ={rel_typ}')
                return latest_pddb_file
            else:
                logger.info(f'No PDDB FILE latest for trunk of type={rel_typ}')

        pddb_file = self.get_latest_file(file_name_pattern=rf'^{self.build}')
        if pddb_file:
            logger.info(f'PDDB FILE latest: {pddb_file} for build={self.build}')
            self.set_pddb_version_from_file_name(pddb_file)
            return pddb_file
        else:
            logger.info(f'No PDDB FILE latest for build={self.build}')

        build_rel, _, _, _ = self.decompose_build_id(self.build)
        pddb_file = self.get_latest_file_of_rel(build_rel)
        if pddb_file:
            logger.info(f'PDDB FILE latest: {pddb_file} for build rel={build_rel}')
            self.set_pddb_version_from_file_name(pddb_file)
            return pddb_file
        else:
            logger.info(f'No PDDB FILE latest for build rel={build_rel}')

        latest_pddb_file = self.get_latest_file(file_name_pattern=rf'^{self.pddb_release}.+')
        if latest_pddb_file:
            logger.info(f'PDDB FILE latest pddb: {latest_pddb_file} for pddb release={self.pddb_release}')
            self.set_pddb_version_from_file_name(latest_pddb_file)
            return latest_pddb_file
        else:
            logger.info(f'No PDDB FILE latest pddb for pddb release={self.pddb_release}')

        pddb_rel_alpha_matches = re.search(r'^(\D+).*', self.pddb_release)
        if pddb_rel_alpha_matches:
            pddb_rel_alpha = pddb_rel_alpha_matches.group(1)
            logger.info(f"*** WARNING: Missing pddb file for release: {self.pddb_release}. ")
            logger.info("Trying to search for pddb by release_type")
            latest_pddb_file = self.get_latest_file(file_name_pattern=rf'^{pddb_rel_alpha}.+')
            self.set_pddb_version_from_file_name(latest_pddb_file)
            logger.info(f'PDDB FILE latest release type: {latest_pddb_file} for pddb rel={pddb_rel_alpha}')
            return latest_pddb_file
        else:
            logger.info(f'No PDDB FILE latest release type for pddb rel={self.pddb_release}')
        return ''

    def get_pddb_file_from_map(self):
        if self.build.endswith('.txt'):
            self.build = os.path.basename(self.build)
            self.pddb_version = self.build.strip('.txt')

        elif self.PDDB_MAP_PATH.is_file():
            pddb_file = self._get_pddb_from_pddb_map()
            if pddb_file:
                return pddb_file

    def _get_pddb_from_pddb_map(self):  # noqa: C901
        pddb_map_dict = {}
        with self.PDDB_MAP_PATH.open(mode='r', encoding='utf-8') as pddb_map:
            for line in pddb_map:
                if ' => ' not in line:
                    continue

                build, pddb_file = line.strip().split(' => ')
                strip_quotes = methodcaller("strip", "'")
                build = strip_quotes(build)
                pddb_file = strip_quotes(pddb_file.strip(','))

                if build == self.build:
                    self.pddb_version = pddb_file.rstrip('.txt')
                    logger.info(f"PDDB File for build {self.build} is {pddb_file}")
                    return pddb_file

                pddb_map_dict[build] = pddb_file

        logger.info(f"Build not found in map: {self.build}")
        self.get_pddb_version_from_network()
        build = self.build
        bld_rel, bld_type, bld_major, bld_minor = self.decompose_build_id(build)
        if not bld_rel:
            return ''

        if bld_rel.startswith('SBTS00') and self.pddb_release.startswith('SBTS'):
            bld_rel = self.pddb_release

        logger.info(f"Searching for PDDB in map rel={bld_rel}, type={bld_type} major={bld_major}, minor={bld_minor}")
        bld_major_minor = int(bld_major + bld_minor)
        lo_candidates = {}
        hi_candidates = {}

        for map_build_id in sorted(pddb_map_dict.keys(), key=str):
            map_bld_rel, map_bld_type, map_bld_major, map_bld_minor = self.decompose_build_id(build=map_build_id)
            if bld_type != map_bld_type:
                continue

            if bld_rel == '00':
                if self.rel_typ(map_bld_rel) != self.rel_typ(bld_rel):
                    continue
            else:
                if map_bld_rel != bld_rel:
                    continue

            map_bld_major_minor = int(map_bld_major + map_bld_minor)

            if map_bld_major_minor <= bld_major_minor:
                if map_bld_major_minor == 0:
                    lo_candidates[map_bld_rel] = pddb_map_dict[map_build_id]
                else:
                    hi_candidates[map_bld_rel] = pddb_map_dict[map_build_id]

        for map_bld_rel in sorted(hi_candidates, key=str):
            logger.info(f"Found high candidate: {map_bld_rel}: {hi_candidates[map_bld_rel]}")
            if hi_candidates[map_bld_rel].endswith('.txt'):
                self.pddb_version = hi_candidates[map_bld_rel].rstrip('.txt')
                self.pddb_release = map_bld_rel
                self.set_pddb_version(self.pddb_version)
                return hi_candidates[map_bld_rel]

        for map_bld_rel in sorted(lo_candidates, key=str):
            logger.info(f"Found low candidate: {map_bld_rel}: {lo_candidates[map_bld_rel]}")
            if lo_candidates[map_bld_rel].endswith('.txt'):
                self.pddb_version = lo_candidates[map_bld_rel].rstrip('.txt')
                self.pddb_release = map_bld_rel
                self.set_pddb_version(self.pddb_version)
                return lo_candidates[map_bld_rel]

        logger.info(f"No PDDB candidates found in map for build: {self.build}")

    def get_latest_file(self, file_name_pattern=''):
        pddb_file_list = [
            f for f in listdir(self.PDDB_PATH) if
            isfile(join(self.PDDB_PATH, f)) and f.endswith('.txt')
        ]
        filtered_files = list(filter(lambda v: re.match(file_name_pattern, v), pddb_file_list))
        return sorted(filtered_files, key=str)[-1] if filtered_files else ''

    def get_latest_file_of_rel(self, rel):
        if not rel:
            return ''
        pddb_file_list = [
            f for f in sorted(listdir(self.PDDB_PATH)) if
            isfile(join(self.PDDB_PATH, f)) and f.endswith('.txt')
        ]
        filtered_files = []
        for pddbf in pddb_file_list:
            rel_str, _, _, _ = self.decompose_pddb_ver(pddbf)
            if rel_str == rel:
                if 'FSM3' in self.build:
                    if 'FSM3' in pddbf:
                        filtered_files.append(pddbf)
                else:
                    filtered_files.append(pddbf)
        # print("rel={}. pddb_file_list={}, filtered_files={}".format(rel, pddb_file_list, filtered_files))
        return sorted(filtered_files, key=str)[-1] if filtered_files else ''

    def get_latest_file_of_typ(self, typ):
        pddb_file_list = [
            f for f in sorted(listdir(self.PDDB_PATH)) if
            isfile(join(self.PDDB_PATH, f)) and f.endswith('.txt')
        ]
        filtered_files = []
        for pddbf in pddb_file_list:
            rel_str, _, _, _ = self.decompose_pddb_ver(pddbf)
            typf = self.rel2typ(rel_str)
            if typf == typ:
                if 'FSM3' in self.build:
                    if 'FSM3' in pddbf:
                        filtered_files.append(pddbf)
                else:
                    filtered_files.append(pddbf)
        # print("typ={}. pddb_file_list={}, filtered_files={}".format(typ, pddb_file_list, filtered_files))
        return sorted(filtered_files, key=str)[-1] if filtered_files else ''

    def set_pddb_version_from_file_name(self, file_name):
        matches = re.match(r'^([^_]+)_(.*)\.txt', file_name)
        if matches:
            self.pddb_release = matches.group(1)
            self.pddb_version = matches.group(1) + "_" + matches.group(2)

    def decompose_build_id(self, build):
        matches = re.match(r'^([^_]+)_(\S+)_(\d+)_(\d+)$', build)
        if matches:
            bld_rel = matches.group(1)
            bld_type = matches.group(2)
            bld_major = matches.group(3)
            bld_minor = matches.group(4)
            return bld_rel, bld_type, bld_major, bld_minor
        matches = re.match(r'^([^_]+)_(\d+)\.(\d+)\.(\d+)$', build)
        if matches:
            bld_rel = matches.group(1)
            bld_type = matches.group(2)
            bld_major = matches.group(3)
            bld_minor = matches.group(4)
            return bld_rel, bld_type, bld_major, bld_minor
        return '', '', '', ''

    def rel2dec(self, rel_str):
        subrel_map = {
            'ASP1': 0.8,
            'C':    0.8,
            'ASP':  0.7,
            'B':    0.7,
            'A':    0.5,
            'S4':   0.5,
            'SP':   0.2,
            'R':    0.0,
        }
        try:
            srch = re.search(self.RELEASE_PATT, rel_str)
            # r_typ = srch.group(1)
            r_rel = srch.group(2)
            r_sub_rel_des = srch.group(3)
            r_sub_rel_dig = srch.group(4)
            sub_rel = 0.0
            if r_sub_rel_des:
                sub_rel = subrel_map[r_sub_rel_des]
                if r_sub_rel_dig:
                    sub_rel += float('0.' + r_sub_rel_dig)
            return str(int(r_rel) + sub_rel)
        except Exception as exc:
            raise Exception("Wrong release: {} ({})".format(rel_str, exc))

    def rel2typ(self, rel_str):
        typ_pattern = r'^([^\d]+)'
        srch = re.search(typ_pattern, rel_str)
        if srch:
            return srch.group(1)
        return rel_str

    def decompose_pddb_ver(self, pddb_version):
        if '_NIDD_' in pddb_version:
            version_groups = re.search(r'([^_]+)_NIDD_(\d+)_(\d+)', pddb_version)
        else:
            version_groups = re.search(r'([^_]+)_(\d+)_(\d+)', pddb_version)
        if version_groups:
            rel_str = version_groups.group(1)
            major = version_groups.group(2).lstrip('0')
            minor = version_groups.group(3).lstrip('0')

            rel_dec_str = self.rel2dec(rel_str)
            rel_float_str = rel_dec_str + major
            return rel_str, rel_float_str, major, minor
        return '', '', '', ''

    def get_pddb_version_from_network(self):
        if self.build.endswith('.txt'):
            pddb_version = self.build.rstrip('.txt')
        else:
            pddb_version = self.get_pddb_version_from_wft()

        if pddb_version is None:
            return

        if 'SBTS00' in self.build and (pddb_version.startswith('FL') or pddb_version.startswith('TL')):
            pddb_version = "SBTS" + pddb_version[2:]

        if not pddb_version or pddb_version == 'unknown':
            pddb_version = self.build
        self.set_pddb_version(pddb_version)

    def get_pddb_version_from_wft(self):

        address = rf'https://wft.int.net.nokia.com/ext/build_content/{self.build}'
        tree = self.get_build_configuration_xml(address)
        if not tree:
            return None

        pddb_version = ''
        for child in tree.findall('./content/'):
            title = child.get('title')
            if title in ['PDDB_RADIO', 'NIDD_RADIO', 'NIDD_FDD', 'NIDD_TDD']:
                pddb_version = child.text
                break

        if not pddb_version:
            for child in tree.findall('./baseline_configurations/baseline_configuration/baseline'):
                title = child.get('title')
                if title in ['PDDB_RADIO', 'NIDD_RADIO']:
                    pddb_version = child.text
                    break

        pddb_version_matches = re.match(r'([\w.]+)(_PDDB_RADIO_|_RADIO_)(\d+)_(\d+).*', pddb_version)
        if pddb_version_matches:
            logger.info(f"PDDB version from build configuration: {pddb_version}")
            return '_'.join(pddb_version_matches.group(1, 3, 4))
        else:
            logger.info("Cannot get PDDB version from branch.")
            return None

    @staticmethod
    def get_build_configuration_xml(address):
        logger.info(f"Downloading build info from :{address}")
        build_configuration_xml = ''
        try:
            build_configuration_xml = ET.fromstring(requests.get(address).text)
        except InvalidSchema:
            logger.info("Build not found")
        except (requests.exceptions.ConnectionError, ET.ParseError):
            logger.info("Address not found")
        return build_configuration_xml

    @staticmethod
    def rel_typ(bld_rel):
        return re.search(r'\D+', bld_rel)

    def set_rel_n1(self):
        match = re.search(r'(?P<rel_typ>\D+)(?P<rel_rel>.*)', self.pddb_release)
        if 'FSM3' in self.build:
            pddb_dir_releases = [f.rstrip('.yaml') for f in listdir(self.ENB_PARAMS_PATH)
                                 if f.startswith(match['rel_typ']) and f.endswith('.yaml') and 'FSM3' in f]
        else:
            pddb_dir_releases = [f.rstrip('.yaml') for f in listdir(self.ENB_PARAMS_PATH)
                                 if f.startswith(match['rel_typ']) and f.endswith('.yaml') and 'FSM3' not in f]

        release_map = {release: self.rel2dec(release) for release in pddb_dir_releases}
        current_rel = re.search(r'(\d+\.\d).*', str(self.pddb_release_number)).group(1)
        for pddb_release, release_dec in sorted(release_map.items(), key=lambda x: float(x[1]), reverse=True):
            if float(release_dec) < float(current_rel):
                logger.info(f"RELEASE N-1: {release_dec} (for current N: {current_rel})")
                self.pddb_release_n1 = pddb_release
                self.pddb_release_number_n1 = release_dec
                break

        self.pddb_filename_n1 = self.PDDB_PATH / self.get_latest_file(self.pddb_release_n1)
